import Component from "@glimmer/component";
import { on } from "@ember/modifier";
import { action } from "@ember/object";
import { service } from "@ember/service";
import { themePrefix } from "virtual:theme";
import BulkSelectCheckbox from "discourse/components/topic-list/bulk-select-checkbox";
import TopicExcerpt from "discourse/components/topic-list/topic-excerpt";
import TopicLink from "discourse/components/topic-list/topic-link";
import UnreadIndicator from "discourse/components/topic-list/unread-indicator";
import TopicPostBadges from "discourse/components/topic-post-badges";
import TopicStatus from "discourse/components/topic-status";
import avatar from "discourse/helpers/avatar";
import { categoryLinkHTML } from "discourse/helpers/category-link";
import concatClass from "discourse/helpers/concat-class";
import icon from "discourse/helpers/d-icon";
import discourseTags from "discourse/helpers/discourse-tags";
import formatDate from "discourse/helpers/format-date";
import number from "discourse/helpers/number";
import topicFeaturedLink from "discourse/helpers/topic-featured-link";
import { shortDateNoYear } from "discourse/lib/formatter";
import { or } from "discourse/truth-helpers";
import { i18n } from "discourse-i18n";
import { getTopicStatusBadge } from "../../lib/topic-status-badge";

export default class HighContextTopicCard extends Component {
  @service capabilities;

  get hasSolved() {
    return (
      this.args.topic.has_accepted_answer || this.args.topic.accepted_answer
    );
  }

  get hasVotes() {
    return this.args.topic.can_vote && this.args.topic.vote_count > 0;
  }

  get voteCountLabel() {
    return i18n(themePrefix("vote_count"), {
      count: this.args.topic.vote_count,
    });
  }

  get hasAssigned() {
    return this.args.topic.assigned_to_user || this.hasIndirectAssignments;
  }

  get assignedUser() {
    return this.args.topic.assigned_to_user;
  }

  get hasIndirectAssignments() {
    const indirect = this.args.topic.indirectly_assigned_to;
    return indirect && Object.keys(indirect).length > 0;
  }

  get indirectAssignees() {
    const indirect = this.args.topic.indirectly_assigned_to;
    if (!indirect) {
      return [];
    }
    return Object.values(indirect).map((assignment) => ({
      user: assignment.assigned_to,
      postNumber: assignment.post_number,
    }));
  }

  get hasTags() {
    return this.args.topic.tags?.length > 0;
  }

  get hasReplies() {
    return this.args.topic.replyCount > 0;
  }

  get hasLikes() {
    return this.args.topic.like_count > 0;
  }

  get replyCountLabel() {
    return i18n(themePrefix("reply_count"), {
      count: this.args.topic.replyCount,
    });
  }

  get likeCountLabel() {
    return i18n(themePrefix("like_count"), {
      count: this.args.topic.like_count,
    });
  }

  get hasExcerpt() {
    return this.args.topic.excerpt || this.args.topic.hasExcerpt;
  }

  get statusBadge() {
    return getTopicStatusBadge(this.args.topic);
  }

  get topicCreator() {
    return this.args.topic.creator;
  }

  get lastPoster() {
    return {
      user: this.args.topic.lastPosterUser,
      username: this.args.topic.last_poster_username,
    };
  }

  get topicTimestamp() {
    return shortDateNoYear(new Date(this.args.topic.created_at));
  }

  @action
  onTitleFocus(event) {
    event.target.closest(".topic-list-item").classList.add("selected");
  }

  @action
  onTitleBlur(event) {
    event.target.closest(".topic-list-item").classList.remove("selected");
  }

  <template>
    {{#if @bulkSelectEnabled}}
      <BulkSelectCheckbox
        @topic={{@topic}}
        @isSelected={{@isSelected}}
        @onToggle={{@onBulkSelectToggle}}
        class="hc-topic-card__bulk-select"
      />
    {{/if}}

    <td class="hc-topic-card">
      <div class="hc-topic-card__header">
        <div class="hc-topic-card__op">
          <div class="hc-topic-card__avatar">
            {{avatar this.topicCreator imageSize="medium"}}
          </div>
          <div class="hc-topic-card__op-info">
            <span class="hc-topic-card__op-timestamp">
              {{i18n (themePrefix "posted")}}
              {{this.topicTimestamp}}
            </span>
            <span class="hc-topic-card__op-name">
              {{i18n
                (themePrefix "by_username")
                username=this.topicCreator.username
              }}</span>
          </div>

        </div>
        <div class="hc-topic-card__status-tags">
          {{#if this.hasSolved}}
            <span class="hc-topic-card__status --solved">
              {{#if this.capabilities.viewport.sm}}
                {{i18n (themePrefix "solved")}}
              {{/if}}
              {{icon "square-check"}}
            </span>
          {{/if}}

          {{#if this.statusBadge}}
            <span
              class={{concatClass
                "hc-topic-card__status"
                this.statusBadge.className
              }}
            >
              {{icon this.statusBadge.icon}}

              {{#if this.capabilities.viewport.sm}}
                <span class="hc-topic-card__status-text">{{i18n
                    this.statusBadge.text
                  }}</span>
              {{/if}}
            </span>
          {{/if}}
        </div>
      </div>

      <div class="hc-topic-card__content">
        <div class="hc-topic-card__title">
          <TopicStatus @topic={{@topic}} @context="topic-list" />
          <TopicLink
            {{on "focus" this.onTitleFocus}}
            {{on "blur" this.onTitleBlur}}
            @topic={{@topic}}
            class="hc-topic-card__title raw-link raw-topic-link"
          />
          {{~#if @topic.featured_link~}}
            &nbsp;{{topicFeaturedLink @topic}}
          {{~/if~}}
          <UnreadIndicator @topic={{@topic}} />
          <TopicPostBadges
            @unreadPosts={{@topic.unread_posts}}
            @unseen={{@topic.unseen}}
            @url={{@topic.lastUnreadUrl}}
          />
        </div>

        {{#if this.hasExcerpt}}
          <TopicExcerpt @topic={{@topic}} class="hc-topic-card__excerpt" />
        {{/if}}
      </div>

      {{#if (or this.hasReplies this.hasAssigned)}}
        <div class="hc-topic-card__context">
          {{#if this.hasReplies}}
            <div class="hc-topic-card__last-reply">
              {{avatar this.lastPoster.user imageSize="tiny"}}
              <span
                class="hc-topic-card__last-reply-name"
              >{{this.lastPoster.username}}</span>
              <span>{{i18n (themePrefix "replied")}}</span>
              <span class="hc-topic-card__time">
                {{formatDate @topic.bumpedAt leaveAgo="true"}}
              </span>
            </div>
          {{/if}}
          {{#if this.hasAssigned}}
            {{#if this.assignedUser}}
              <div class="hc-topic-card__assigned">
                {{icon "user-plus"}}
                <span
                  class="hc-topic-card__assigned-name"
                >{{this.assignedUser.username}}</span>
              </div>
            {{/if}}
            {{#each this.indirectAssignees as |assignment|}}
              <div class="hc-topic-card__assigned">
                {{icon "user-plus"}}
                <span
                  class="hc-topic-card__assigned-name"
                >{{assignment.user.username}}</span>
                <span
                  class="hc-topic-card__assigned-post"
                >#{{assignment.postNumber}}</span>
              </div>
            {{/each}}
          {{/if}}
        </div>
      {{/if}}

      <div class="hc-topic-card__footer">
        <div class="hc-topic-card__category-tags">
          {{#unless @hideCategory}}
            <div class="hc-topic-card__category">
              {{categoryLinkHTML @topic.category}}
            </div>
          {{/unless}}

          {{#if this.hasTags}}
            {{discourseTags @topic mode="list" className="hc-topic-card__tags"}}
          {{/if}}
        </div>

        <div class="hc-topic-card__stats">
          {{#if this.hasVotes}}
            <span
              class="hc-topic-card__votes"
              aria-label={{this.voteCountLabel}}
              title={{this.voteCountLabel}}
            >
              {{icon "check-to-slot" skipTitle=true}}
              <span class="hc-topic-card__votes-count">{{number
                  @topic.vote_count
                }}</span>
            </span>
          {{/if}}

          {{#if this.hasReplies}}
            <span
              class="hc-topic-card__replies"
              aria-label={{this.replyCountLabel}}
              title={{this.replyCountLabel}}
            >
              {{icon "reply" skipTitle=true}}
              <span class="hc-topic-card__count">{{number
                  @topic.replyCount
                }}</span>
            </span>
          {{/if}}

          {{#if this.hasLikes}}
            <span
              class="hc-topic-card__likes"
              aria-label={{this.likeCountLabel}}
              title={{this.likeCountLabel}}
            >
              {{icon "heart" skipTitle=true}}
              <span class="hc-topic-card__count">{{number
                  @topic.like_count
                }}</span>
            </span>
          {{/if}}
        </div>
      </div>
    </td>
  </template>
}

import Component from "@glimmer/component";
import { tracked } from "@glimmer/tracking";
import { action } from "@ember/object";
import { service } from "@ember/service";
import { isEmpty } from "@ember/utils";
import { Promise } from "rsvp";
import DMenu from "discourse/float-kit/components/d-menu";
import concatClass from "discourse/helpers/concat-class";
import icon from "discourse/helpers/d-icon";
import { reload } from "discourse/helpers/page-reloader";
import { ajax } from "discourse/lib/ajax";
import {
  listColorSchemes,
  updateColorSchemeCookie,
} from "discourse/lib/color-scheme-picker";
import cookie from "discourse/lib/cookie";
import UserColorPaletteMenuItem from "./user-color-palette-menu-item";

const HORIZON_PALETTES = [
  "Horizon",
  "Marigold",
  "Violet",
  "Lily",
  "Clover",
  "Royal",
];

export default class UserColorPaletteSelector extends Component {
  @service currentUser;
  @service site;
  @service session;

  @tracked anonColorPaletteId = this.#loadAnonColorPalette();
  @tracked userColorPaletteId = this.session.userColorSchemeId;
  @tracked cssLoaded = true;

  get userColorPalettes() {
    const availablePalettes = listColorSchemes(this.site)
      ?.map((userPalette) => {
        const hex = userPalette.colors.find(
          (color) => color.name === "tertiary"
        )?.hex;
        return {
          ...userPalette,
          accent: hex && `#${hex}`,
        };
      })
      .filter((userPalette) => {
        return HORIZON_PALETTES.some((palette) => {
          return (
            userPalette.name.toLowerCase().includes(palette.toLowerCase()) &&
            userPalette.accent
          );
        });
      })
      .sort();

    // Match the light scheme with the corresponding dark id based in the name
    return (
      availablePalettes
        ?.map((palette) => {
          if (palette.is_dark) {
            return palette;
          }

          const normalizedLightName = palette.name.toLowerCase();

          const correspondingDarkModeId = availablePalettes.find(
            (item) =>
              item.is_dark &&
              normalizedLightName ===
                item.name.toLowerCase().replace(/\s+dark$/, "")
          )?.id;

          return {
            ...palette,
            correspondingDarkModeId,
          };
        })
        // Only want to show palettes that have corresponding light/dark modes
        .filter((palette) => !palette.is_dark)
    );
  }

  get selectedColorPaletteId() {
    if (this.currentUser) {
      return this.userColorPaletteId;
    }

    return this.anonColorPaletteId;
  }

  @action
  onRegisterMenu(api) {
    this.dMenu = api;
  }

  @action
  paletteSelected(selectedPalette) {
    if (selectedPalette.id === this.selectedColorPaletteId) {
      return;
    }

    this.#updatePreference(selectedPalette);
    this.#changeSiteColorPalette(selectedPalette);
    this.dMenu.close();
  }

  #updatePreference(selectedPalette) {
    updateColorSchemeCookie(selectedPalette.id);
    updateColorSchemeCookie(selectedPalette.correspondingDarkModeId, {
      dark: true,
    });

    if (!this.currentUser) {
      this.anonColorPaletteId = selectedPalette.id;
    } else {
      this.userColorPaletteId = selectedPalette.id;
    }
  }

  #loadAnonColorPalette() {
    const storedAnonPaletteId = cookie("color_scheme_id");
    if (storedAnonPaletteId) {
      return parseInt(storedAnonPaletteId, 10);
    }
  }

  async #changeSiteColorPalette(colorPalette) {
    this.cssLoaded = false;

    const lightPaletteId = colorPalette.id;
    const darkPaletteId = colorPalette.correspondingDarkModeId;
    const darkTag = document.querySelector("link.dark-scheme");

    // TODO(osama) once we have built-in light/dark modes for each palette, we
    // can stop making the 2nd ajax call for the dark palette and replace it
    // with a include_dark_scheme param on the ajax call for the light
    // palette which will include the href for the dark palette in the response
    if (!darkTag) {
      reload();
      return;
    }

    const lightPaletteInfo = await ajax(
      `/color-scheme-stylesheet/${lightPaletteId}/${colorPalette.theme_id}.json`
    );
    const darkPaletteInfo = await ajax(
      `/color-scheme-stylesheet/${darkPaletteId}/${colorPalette.theme_id}.json`
    );

    Promise.all([
      this.#preloadAndSwapCSS(lightPaletteInfo.new_href, "light-scheme"),
      this.#preloadAndSwapCSS(darkPaletteInfo.new_href, "dark-scheme"),
    ]).then(() => {
      this.cssLoaded = true;
    });
  }

  #preloadAndSwapCSS(newHref, existingLinkClass) {
    return new Promise((resolve) => {
      const existingLink = document.querySelector(
        `link[rel='stylesheet'].${existingLinkClass}`
      );
      const newTag = document.createElement("link");

      newTag.rel = "preload";
      newTag.href = newHref;
      newTag.as = "style";
      newTag.onload = () => {
        existingLink.href = newHref;
        newTag.remove();
        resolve();
      };

      document.head.appendChild(newTag);
    });
  }

  <template>
    {{#unless (isEmpty this.userColorPalettes)}}
      <DMenu
        @identifier="user-color-palette-selector"
        @placementStrategy="fixed"
        @onRegisterApi={{this.onRegisterMenu}}
        class={{concatClass
          "btn-flat user-color-palette-selector sidebar-footer-actions-button"
          (if this.cssLoaded "user-color-palette-css-loaded")
        }}
        data-selected-color-palette-id={{this.selectedColorPaletteId}}
        @inline={{true}}
      >
        <:trigger>
          {{icon "paintbrush"}}
        </:trigger>
        <:content>
          <div class="user-color-palette-menu">
            <div class="user-color-palette-menu__content">
              {{#each this.userColorPalettes as |colorPalette|}}
                <UserColorPaletteMenuItem
                  @selectedColorPaletteId={{this.selectedColorPaletteId}}
                  @colorPalette={{colorPalette}}
                  @paletteSelected={{this.paletteSelected}}
                />
              {{/each}}
            </div>
          </div>
        </:content>
      </DMenu>
    {{/unless}}
  </template>
}

@use "lib/viewport";

:root {
  --d-button-border-radius: 6.25rem;
}

.discourse-no-touch .topic-body .actions .fade-out {
  transition: none;
}

.sidebar-new-topic-button__wrapper {
  &:has(.fk-d-tooltip__trigger) {
    #create-topic.btn {
      border-radius: var(--d-button-border-radius) 0 0
        var(--d-button-border-radius);
    }
  }
}

.discourse-no-touch .btn-default.sidebar-new-topic-button,
.discourse-no-touch .btn-default,
.discourse-no-touch .select-kit .select-kit-header.btn-default {
  background: var(--primary-100);

  .d-icon {
    color: var(--accent-color);
  }

  &:focus-visible,
  &:hover {
    background: var(--primary-100);
    color: var(--primary);
    box-shadow: 0 0 0 4px var(--button-box-shadow);

    .d-icon {
      color: var(--accent-color);
    }
  }

  &:active:not(:hover, :focus) {
    color: var(--primary);
    background: var(--tertiary-300);
    background-image: none;

    .d-icon {
      color: var(--tertiary-high);
    }
  }
}

.btn-primary,
.discourse-no-touch .btn-default.ai-new-question-button {
  background-color: var(--accent-color);
  color: var(--accent-text-color);

  .d-icon {
    color: var(--accent-text-color);
  }

  &:not([disabled]):focus-visible,
  &:not([disabled]):hover {
    .discourse-no-touch & {
      background-color: var(--accent-color);
      box-shadow: 0 0 0 4px var(--button-box-shadow);
      color: var(--accent-text-color);

      .d-icon {
        color: var(--accent-text-color);
      }
    }
  }

  &:active {
    background: light-dark(
      oklch(from var(--accent-color) 40% c h),
      oklch(from var(--accent-color) 50% c h)
    );
  }

  &:visited {
    color: var(--accent-text-color);
  }
}

.btn-danger {
  .discourse-no-touch & {
    &:not([disabled]):focus-visible,
    &:not([disabled]):hover {
      background-color: var(--danger);
      box-shadow: 0 0 0 4px var(--d-button-danger-bg-color--hover);
    }
  }
}

// DiscoToc plugin
.d-toc-main,
.timeline-footer-controls {
  .btn.timeline-toggle {
    border-top-right-radius: 8px;
    border-top-left-radius: 8px;
    border-bottom-left-radius: 0;
    border-bottom-right-radius: 0;
    bottom: var(--main-grid-gap);
  }
}

.d-combo-button:hover {
  border-radius: var(--d-button-border-radius);
  box-shadow: 0 0 0 4px var(--button-box-shadow);

  button:hover {
    // remove duplicate shadow from child button
    box-shadow: none;
  }
}

@use "lib/viewport";

.list-container.--categories {
  .avatar-flair {
    display: none;
  }
}

.categories-and-latest {
  .category-list {
    border-collapse: separate;

    th.topics,
    .category-logo {
      display: none;
    }

    thead tr th {
      font-size: var(--font-up-1-rem);
      font-weight: bold;
    }

    tbody {
      display: flex;
      flex-direction: column;
      gap: 1em;
      padding-top: 1em;
      border: 0;
    }

    tbody tr {
      display: grid;
      grid-template-areas:
        "title topics"
        "category category"
        "subcategory subcategory";
      row-gap: 1em;
      border: 1px solid var(--primary-300);
      border-radius: var(--d-border-radius-large);
      box-shadow: 0 0 12px 1px var(--topic-card-shadow);
    }

    td.category {
      display: contents;
      border-top-left-radius: var(--d-border-radius-large);
      border-bottom-left-radius: var(--d-border-radius-large);
      border-width: 2px;
      padding: 1em 1.5rem;
    }

    tbody h3 {
      grid-area: title;
      padding: 1em 0 0 1.5rem;
      font-size: var(--font-up-1-rem);

      .category-name {
        display: flex;
        align-self: center;
      }

      .badge-category {
        gap: 0.25em;
        align-items: center;
        font-size: var(--font-up-1-rem);

        .d-icon:first-of-type:not([class*="d-icon-category.restricted"]),
        &.--style-square::before,
        &.--style-emoji .emoji {
          width: 1.25em;
          height: 1.25em;
          margin-right: 0.25em;
        }

        &.--style-square::before {
          border-radius: 6px;
        }
      }

      [class*="d-icon-category.restricted"] {
        order: 1;
      }
    }

    .topics {
      width: auto;
      padding: 1em 1.5rem 0 0;
      display: flex;
      align-items: center;
      justify-content: end;
    }

    .category-description {
      grid-area: category;
      padding: 0 1.5rem;
      margin: 0;
      font-size: var(--font-down-1-rem);
    }

    .subcategories {
      grid-area: subcategory;
      gap: 0.25em 0.5em;
      padding: 0 1.5rem 1em;
      margin: 0;

      .badge-category__wrapper {
        background-color: var(--badge-category-bg);
        padding: 0.25em 0.5rem;
        border-radius: var(--d-border-radius);
      }

      .badge-category__name {
        color: var(--badge-category-text);
      }

      .badge-category.--style-square::before {
        border-radius: 3px;
      }
    }
  }

  .latest-topic-list {
    .table-heading {
      border: 0;
      font-size: var(--font-up-1-rem);
      font-weight: bold;
    }

    &-item {
      display: grid;
      grid-template-columns: min-content min-content auto min-content;
      grid-template-areas:
        "creator title title status"
        ". category activity activity";
      column-gap: 0.75rem;
      row-gap: 0.5rem;
      background: var(--d-content-background);
      box-shadow: 0 0 12px 1px var(--topic-card-shadow);
      text-overflow: ellipsis;
      padding: 0.75em 1rem;
      border: 1px solid var(--primary-300);
      border-radius: var(--d-border-radius-large);
      margin-top: 1em;
    }

    .main-link,
    .topic-stats {
      display: contents;
    }

    .top-row {
      grid-area: title;
    }

    .bottom-row {
      grid-area: category;

      .discourse-tags {
        display: none;
      }
    }

    .badge-category__wrapper {
      border-radius: var(--d-border-radius);
      padding: 0.25em 0.5rem;
      background-color: var(--badge-category-bg);

      @include viewport.until(md) {
        padding: 0.25em 0.5rem;
        font-size: var(--font-down-2);
      }

      .badge-category__name {
        color: var(--badge-category-text);
      }
    }

    .topic-list-data {
      grid-area: likes-replies;
    }

    .num.posts-map {
      display: none;
    }

    .topic-last-activity {
      grid-area: activity;
      display: flex;
      align-items: center;
      text-align: left;
      font-size: var(--font-down-1-rem);

      &::before {
        content: "";
        display: inline-block;
        width: 0.25em;
        height: 0.25em;
        background-color: var(--primary-500);
        border-radius: 100%;
        margin-right: 0.5em;
      }
    }

    .topic-poster {
